mapper.update:
UPDATE nw_chat_messages SET input_references=#{references,typeHandler=com.skillforge.core.chat.persistence.ChatReferencesTypeHandler}
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND role='user'
  AND metadata->>'input_id'=#{inputId}
  AND input_references='[]'::jsonb
  AND input_references IS DISTINCT FROM #{references,typeHandler=com.skillforge.core.chat.persistence.ChatReferencesTypeHandler}

mapper.select:
SELECT id, tenant_id, session_id, end_user_id, message_id, role, content, metadata, created_at, message_version, input_references
FROM nw_chat_messages
WHERE tenant_id = #{tenantId}
  AND metadata ->> 'execution_id' = #{executionId}
ORDER BY created_at ASC
